css:
.loader { width: calc(var(--loader-size) * .4); height: var(--loader-size); border-radius: calc(var(--loader-size) * .12); background: #1f2937; display: flex; flex-direction: column; align-items: center; justify-content: space-around; padding: calc(var(--loader-size) * .06) 0; box-sizing: border-box; }
.loader span { width: 62%; aspect-ratio: 1; border-radius: 50%; }
.loader span:nth-child(1) { background: #ef4444; animation: tl-a calc(var(--loader-speed) * 3) infinite; }
.loader span:nth-child(2) { background: #f59e0b; animation: tl-b calc(var(--loader-speed) * 3) infinite; }
.loader span:nth-child(3) { background: #22c55e; animation: tl-c calc(var(--loader-speed) * 3) infinite; }
@keyframes tl-a { 0%, 30% { opacity: 1; box-shadow: 0 0 calc(var(--loader-size) * .1) #ef4444; } 31%, 100% { opacity: .18; box-shadow: none; } }
@keyframes tl-b { 0%, 30% { opacity: .18; } 31%, 63% { opacity: 1; box-shadow: 0 0 calc(var(--loader-size) * .1) #f59e0b; } 64%, 100% { opacity: .18; } }
@keyframes tl-c { 0%, 63% { opacity: .18; } 64%, 100% { opacity: 1; box-shadow: 0 0 calc(var(--loader-size) * .1) #22c55e; } }
